function ratPow(base, exp) {
  if (!ratIsInt(exp) || exp.n > 64n || exp.n < -64n) return null;
  let e = exp.n < 0n ? -exp.n : exp.n;
  let out = rat(1n);
  for (let i = 0n; i < e; i++) out = ratMul(out, base);
  if (exp.n < 0n) return ratDiv(rat(1n), out);
  return out;
}

