  let sign = 1n;
  if (s.startsWith("-")) {
    sign = -1n;
    s = s.slice(1).trim();
  } else if (s.startsWith("+")) s = s.slice(1).trim();
  s = s.replace(/(?<=\d),(?=\d{3}(\D|$))/g, "");
